# Ground truth: asset movements decoded straight from raw call traces
import json,glob,sys
tl=json.load(open('eth-gleeman/data/tokenlist/uniswapToken.json'))
toks={t['address'].lower():(t['symbol'],t['decimals']) for t in (tl['tokens'] if isinstance(tl,dict) else tl) if t.get('chainId',1)==1}
toks.setdefault('0x853d955acef822db058eb8505911ed77f175b99e',('FRAX',18))
def w(x): return '0x'+x[-40:]
out={}
for f in sorted(glob.glob('blind/raw/*.json')):
    t=json.load(open(f)); mv=[]; sender=t['from']
    def walk(c):
        if c.get('type') not in ('CALL',None): 
            for s in c.get('calls',[]): walk(s)
            return
        v=int(c.get('value','0x0'),16); inp=c.get('input','0x'); to=c['to'].lower()
        if v: mv.append(('ETH',c['from'],to,v/1e18))
        sel=inp[:10]; a=inp[10:]
        sym,dec=toks.get(to,(to[:8],18))
        if sel=='0xa9059cbb': mv.append((sym,c['from'],w(a[:64]),int(a[64:128],16)/10**dec))
        if sel=='0x23b872dd': mv.append((sym,w(a[:64]),w(a[64:128]),int(a[128:192],16)/10**dec))
        if sel=='0x2e1a7d4d' and sym=='WETH': mv.append(('WETH-burn',c['from'],to,int(a[:64],16)/1e18))
        for s in c.get('calls',[]): walk(s)
    walk(t)
    name=f.split('/')[-1][:4]; out[name]={'sender':sender,'to':t['to'],'sel':t['input'][:10],'moves':mv}
    print(name,'sender',sender[:8],'->',t['to'][:8],t['input'][:10])
    for m in mv: print('   ',m[0],m[1][:8],'->',m[2][:8],m[3])
json.dump(out,open('work/gt.json','w'),indent=1)
EOF
